#define _K2              ((uint8_t *)_K2)                    // u8[116256] (116256 bytes)
#define _K1              ((uint8_t *)(_state + 0x00000010))  // u8[268288] (268288 bytes)
#define _K5              ((int8_t *)(_state + 0x00000000))   // s8[8] (8 bytes)
#define _K3              ((int8_t *)(_buffer + 0x00000002))  // s8[3760] (3760 bytes)
#define _K4              ((int8_t *)(_buffer + 0x00000000))  // d8[2] (2 bytes)

